#include "string.h"
size_t strlen(const char *сап_берилмелер) { const char *자료위치 = сап_берилмелер; while (*자료위치) 자료위치++; return 자료위치 - сап_берилмелер; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *x_координата = 첫째값, *세로좌표 = 둘째값; while (개수--) { if (*x_координата != *세로좌표) return (int)*x_координата - *세로좌표; x_координата++; 세로좌표++; } return 0; }
void *memmove(void *көздөө_жайы_берилмелер, const void *сап_берилмелер, size_t 개수) { unsigned char *x_координата = көздөө_жайы_берилмелер; const unsigned char *세로좌표 = сап_берилмелер; if (x_координата < 세로좌표) { for (size_t 순번 = 0; 순번 < 개수; 순번++) x_координата[순번] = 세로좌표[순번]; } else { while (개수) { 개수--; x_координата[개수] = 세로좌표[개수]; } } return көздөө_жайы_берилмелер; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char x_координата = *첫째값++, 세로좌표 = *둘째값++; if (x_координата != 세로좌표) return (int)x_координата-세로좌표; if (!x_координата) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *сап_берилмелер, char **аяктоо_Жылбышуу, int Фон_маани) {
    const char *Баштоо_Жылбышуу = сап_берилмелер; unsigned long маани = 0; int коддоо_маани = 1, 하나라도 = 0;
    while (*сап_берилмелер == ' ' || (*сап_берилмелер >= 9 && *сап_берилмелер <= 13)) сап_берилмелер++;
    if (*сап_берилмелер == '-' || *сап_берилмелер == '+') { if (*сап_берилмелер == '-') коддоо_маани = -1; сап_берилмелер++; }
    if (Фон_маани == 0) Фон_маани = 10;
    while (*сап_берилмелер >= '0' && *сап_берилмелер <= '9' && *сап_берилмелер - '0' < Фон_маани) {
        unsigned санарип_маани = *сап_берилмелер++ - '0'; 하나라도 = 1;
        if (маани > (0x7ffffffffffffffful - санарип_маани) / (unsigned)Фон_маани) маани = 0x7ffffffffffffffful;
        else маани = маани * Фон_маани + санарип_маани;
    }
    if (аяктоо_Жылбышуу) *аяктоо_Жылбышуу = (char *)(하나라도 ? сап_берилмелер : Баштоо_Жылбышуу); return коддоо_маани > 0 ? (long)маани : -(long)маани;
}
int atoi(const char *сап_берилмелер) { return (int)strtol(сап_берилмелер, 0, 10); }
